import array,hashlib,json,math,struct,sys
from pathlib import Path
half=[struct.unpack('<e',struct.pack('<H',i))[0] for i in range(65536)]
refpath=Path(sys.argv[1])
refreport=json.loads((refpath/'report.json').read_text());refdata={}
for row in refreport['captures']:
 if row['channel'] in ('hdr_pre_bloom','hdr_post_transmission','ssr_reflection'):
  raw=(refpath/row['data_path']).read_bytes();assert 'sha256:'+hashlib.sha256(raw).hexdigest()==row['data_sha256']
  q=array.array('H');q.frombytes(raw);refdata[row['channel']]=q
results=[]
for arg in sys.argv[2:]:
 run=Path(arg);report=json.loads((run/'report.json').read_text());assert report['status']=='pass'
 result={'run':str(run),'report_sha256':hashlib.sha256((run/'report.json').read_bytes()).hexdigest(),'comparison':'Independent checkpoint replays against320warm checked-static reference; this measures convergence with possible jitter/noise differences, not an exact ghost mask.','channels':{}}
 for name in ['ssr_reflection','hdr_post_transmission','hdr_pre_bloom']:
  rows=[r for r in report['captures'] if r['channel']==name];frames=[]
  for row in rows:
   raw=(run/row['data_path']).read_bytes();assert 'sha256:'+hashlib.sha256(raw).hexdigest()==row['data_sha256']
   data=array.array('H');data.frombytes(raw);assert len(data)==row['width']*row['height']*4
   frames.append(data)
  if not rows: continue
  width,height=rows[0]['width'],rows[0]['height'];reference=refdata[name];regions={}
  for region,box in [('counter_top',(600,390,1420,610)),('bar_front',(530,610,1370,840))]:
   x0,y0,x1,y1=[round(value*scale) for value,scale in zip(box,[width/1509,height/907,width/1509,height/907])]
   measurements=[]
   for row,frame in zip(rows,frames):
    count=0;error=0.;covered_error=0.;above=0;changed=0;mean=0.
    for y in range(y0,y1):
     for x in range(x0,x1):
      i=4*(y*width+x);a=[half[frame[i+k]] for k in range(4)];b=[half[reference[i+k]] for k in range(4)]
      assert all(math.isfinite(v) for v in a+b)
      d=max(abs(a[k]-b[k]) for k in range(3));error+=d;above+=d>.001;count+=1
      covered_error+=max(abs(a[k]*a[3]-b[k]*b[3]) for k in range(3))
      changed+=any(frame[i+k]!=reference[i+k] for k in range(4));mean+=max(a[:3])
    measurements.append({'frame':row['checkpoint_frame'],'mean_abs_max_rgb':error/count,'rgb_delta_gt_0.001':above,'pixels_changed':changed,'mean_abs_covered_rgb':covered_error/count,'mean_max_rgb':mean/count})
   regions[region]={'box':[x0,y0,x1,y1],'pixels':count,'measurements':measurements}
  result['channels'][name]={'extent':[width,height],'regions':regions,'frames':[{ 'frame':r['checkpoint_frame'],'sha256':r['data_sha256']} for r in rows]}
 results.append(result)
print(json.dumps(results,indent=2))
